    const prof = lvl <= 4 ? 2 : lvl <= 8 ? 3 : 4;
    const strMod = 3;
    const conMod = 2;
    const dexMod = 1;
    const hp = 10 + conMod + Math.max(0, lvl - 1) * (5 + conMod);
