    BASE_TEMPLATES,
    DEFAULT_STRINGS,
    listBaseTemplates,
    getTemplateMeta,
    getTemplateIcon,
    getStrings,
    substitute,
    resolveInventory,
    generateSceneFromTemplate,
    generateCompanionScenes,
