    [COMBAT_ROLES.RANGED]: planRangedTurn,
    [COMBAT_ROLES.CASTER]: planCasterTurn,
    [COMBAT_ROLES.TANK]: planTankTurn,
    [COMBAT_ROLES.SUPPORT]: planSupportTurn,
