      if (!this._combatKeyHandlerBound) {
        this._combatKeyHandlerBound = true;
        document.addEventListener('keydown', (e) => {
          if (e.key !== 'Escape') return;
          if (GameEngine.getCombatPhase?.() === 'select_target') {
            e.preventDefault();
            GameEngine.cancelAbilityTargetSelect();
          }
        });
      }
